mapper.select:
SELECT a.project_id 'project.id', a.monomer_id 'monomer.id', a.area_id 'district.id', a.factory_id 'factory.id', a.workshop_id 'workshop.id', a.production_line_id 'production_line.id', a.team_id, DATE_FORMAT( a.create_time, '%Y/%m/%d' ) date, SUM( a.quantity ) quantity, cp.`name` 'project.name', cp.short_name 'project.short_name', cp.serial_number 'project.contract_no', pm.`name` 'monomer.name', pd.`name` 'district.name', mbf.`name` 'factory.name', mbw.`name` 'workshop.name', mbpl.`name` 'production_line.name', ta.`name` `name`, ta.serial_number, ta.net_weight, ta.gross_weight, ta.material, ta.drawing_number, ta.length, ta.surface_area, ta.specification, ta.net_weight*a.quantity total_net_weight, ta.gross_weight*a.quantity total_gross_weight FROM mes_building_complete a LEFT JOIN contract_project cp ON cp.id = a.project_id AND cp.bool_delete_enum = FALSE LEFT JOIN plan_monomer pm ON pm.id = a.monomer_id AND pm.bool_delete_enum = FALSE LEFT JOIN plan_area pd ON pd.id = a.area_id AND pd.bool_delete_enum = FALSE LEFT JOIN mes_building_factory mbf ON mbf.id = a.factory_id AND mbf.bool_delete_enum = FALSE LEFT JOIN mes_building_workshop mbw ON mbw.id = a.workshop_id AND mbw.bool_delete_enum = FALSE LEFT JOIN mes_building_production_line mbpl ON mbpl.id = a.production_line_id AND mbpl.bool_delete_enum = FALSE LEFT JOIN tech_artifact ta ON a.product_id=ta.id AND ta.bool_delete_enum=FALSE WHERE a.bool_delete_enum=FALSE AND a.product_type = ${@com.hzchum.scim.mes.building.core.api.enums.ProductTypeEnum@ARTIFACT.getType()}
AND a.project_id=#{projectId}
AND a.monomer_id=#{monomerId}
AND a.area_id=#{areaId}
AND a.factory_id=#{factoryId}
AND a.workshop_id=#{workshopId}
AND a.productionLine_id=#{productionLineId}
AND ta.name like concat('%',#{name},'%')
AND ta.serial_number like concat('%',#{serialNumber},'%')
AND ta.material like concat('%',#{material},'%')
AND ta.specification like concat('%',#{specification},'%')
AND a.create_time > date(#{satrtDate})
AND a.create_time < date(#{endDate})
GROUP BY a.project_id, a.monomer_id, a.area_id, a.factory_id, a.workshop_id, a.production_line_id, DATE_FORMAT( a.create_time, '%Y-%m%-%d' )

SELECT a.project_id 'project.id', a.monomer_id 'monomer.id', a.area_id 'district.id', a.factory_id 'factory.id', a.workshop_id 'workshop.id', a.production_line_id 'production_line.id', a.team_id, DATE_FORMAT( a.create_time, '%Y/%m/%d' ) date, SUM( a.quantity ) quantity, cp.`name` 'project.name', cp.short_name 'project.short_name', cp.serial_number 'project.contract_no', pm.`name` 'monomer.name', pd.`name` 'district.name', mbf.`name` 'factory.name', mbw.`name` 'workshop.name', mbpl.`name` 'production_line.name', ta.`name` `name`, ta.serial_number, ta.material, ta.width, ta.length, ta.category, ta.plate, ta.length*a.quantity total_net_length, ta.length*ta.width*a.quantity total_area FROM mes_building_complete a LEFT JOIN contract_project cp ON cp.id = a.project_id AND cp.bool_delete_enum = FALSE LEFT JOIN plan_monomer pm ON pm.id = a.monomer_id AND pm.bool_delete_enum = FALSE LEFT JOIN plan_area pd ON pd.id = a.area_id AND pd.bool_delete_enum = FALSE LEFT JOIN mes_building_factory mbf ON mbf.id = a.factory_id AND mbf.bool_delete_enum = FALSE LEFT JOIN mes_building_workshop mbw ON mbw.id = a.workshop_id AND mbw.bool_delete_enum = FALSE LEFT JOIN mes_building_production_line mbpl ON mbpl.id = a.production_line_id AND mbpl.bool_delete_enum = FALSE LEFT JOIN tech_enclosure ta ON a.product_id=ta.id AND ta.bool_delete_enum= FALSE WHERE a.bool_delete_enum= FALSE AND a.product_type = ${@com.hzchum.scim.mes.building.core.api.enums.ProductTypeEnum@ENCLOSURE.getType()}
AND a.project_id=#{projectId}
AND a.monomer_id=#{monomerId}
AND a.area_id=#{areaId}
AND a.factory_id=#{factoryId}
AND a.workshop_id=#{workshopId}
AND a.productionLine_id=#{productionLineId}
AND ta.name like concat('%',#{name},'%')
AND ta.serial_number like concat('%',#{serialNumber},'%')
AND ta.plate like concat('%',#{plate},'%')
AND ta.category in (1,3)
AND ta.category = #{category}
AND a.create_time > date(#{satrtDate})
AND a.create_time < date(#{endDate})
GROUP BY a.project_id, a.monomer_id, a.area_id, a.factory_id, a.workshop_id, a.production_line_id, DATE_FORMAT( a.create_time, '%Y-%m%-%d' )
